#include "DHT.h"

#define DHTPIN 5
#define DHTTYPE DHT11
DHT dht(DHTPIN, DHTTYPE);

const int segmentos[] = {7, 6, 4, 2, 8, 9, 10};

byte digitos[10] = {
  0b00111111, 0b00000110, 0b01011011, 0b01001111, 0b01100110, 
  0b01101101, 0b01111101, 0b00000111, 0b01111111, 0b01101111
};

void setup() {
  for (int i = 0; i < 7; i++) pinMode(segmentos[i], OUTPUT);
  pinMode(13, OUTPUT);
  digitalWrite(13, LOW);
  dht.begin();
}

void loop() {
  digitalWrite(13, LOW);

  float temp = dht.readTemperature();

  if (!isnan(temp)) {
    int valorInteiro = (int)temp;
    int dezena = (valorInteiro / 10) % 10;
    int unidade = valorInteiro % 10;

    mostrarNumero(dezena);
    delay(1000);

    apagarDisplay();
    delay(200);

    mostrarNumero(unidade);
    delay(1000);

    apagarDisplay();
    delay(200);
  }
}

void mostrarNumero(int num) {
  byte padrao = digitos[num];
  for (int i = 0; i < 7; i++) {
    digitalWrite(segmentos[i], bitRead(padrao, i));
  }
}

void apagarDisplay() {
  for (int i = 0; i < 7; i++) digitalWrite(segmentos[i], LOW);
}
